-- An accumulating snapshot: one row per order_id, line_number, updated as it passes each
-- milestone (ordered_on, shipped_on, received_on). A milestone once reached keeps its date, even when
-- a later run does not see it again.

with lineitem as (

    select * from {{ ref('stg_tpch_erp__lineitem') }}

),

orders as (

    select * from {{ ref('stg_tpch_erp__orders') }}

),

incoming as (

    select
        cast(lineitem.l_orderkey as BIGINT) as order_id,
        cast(lineitem.l_linenumber as INTEGER) as line_number,
        coalesce(cast(orders.o_custkey as BIGINT), cast(-1 as BIGINT)) as customer_id,
        cast(orders.o_orderdate as DATE) as ordered_on,
        cast(lineitem.l_commitdate as DATE) as committed_on,
        cast(lineitem.l_shipdate as DATE) as shipped_on,
        cast(lineitem.l_receiptdate as DATE) as received_on,
        cast(current_timestamp as TIMESTAMPTZ) as _updated_at,
        cast(lineitem._ingested_at as TIMESTAMPTZ) as _loaded_at
    from lineitem
    left join orders
        on lineitem.l_orderkey = orders.o_orderkey
{% if is_incremental() %}
    where cast(lineitem._ingested_at as TIMESTAMPTZ) > (select coalesce(max(_loaded_at), cast('1900-01-01' as TIMESTAMPTZ)) from {{ this }})
{% endif %}

),

merged as (

    select
        incoming.order_id,
        incoming.line_number,
        incoming.customer_id,
{% if is_incremental() %}
        coalesce(incoming.ordered_on, reached.ordered_on) as ordered_on,
{% else %}
        incoming.ordered_on,
{% endif %}
        incoming.committed_on,
{% if is_incremental() %}
        coalesce(incoming.shipped_on, reached.shipped_on) as shipped_on,
{% else %}
        incoming.shipped_on,
{% endif %}
{% if is_incremental() %}
        coalesce(incoming.received_on, reached.received_on) as received_on,
{% else %}
        incoming.received_on,
{% endif %}
        incoming._updated_at,
        incoming._loaded_at
    from incoming
{% if is_incremental() %}
    left join {{ this }} as reached
        on reached.order_id = incoming.order_id and reached.line_number = incoming.line_number
{% endif %}

)

select
    merged.order_id,
    merged.line_number,
    merged.customer_id,
    merged.ordered_on,
    merged.committed_on,
    merged.shipped_on,
    merged.received_on,
    merged._updated_at,
    merged._loaded_at,
    {{ dbt.datediff('merged.ordered_on', 'merged.shipped_on', 'day') }} as ordered_on_to_shipped_on_days,
    {{ dbt.datediff('merged.shipped_on', 'merged.received_on', 'day') }} as shipped_on_to_received_on_days,
    case when merged.received_on is not null then 'received_on' when merged.shipped_on is not null then 'shipped_on' when merged.ordered_on is not null then 'ordered_on' end as current_milestone
from merged
